mapper.update:
update safety.safety_employee_message sem join safety.safety_group_info sgi on sem.org_code = sgi.code and sgi.status = 'Y' and sgi.code in
#{item}
set sem.org_name = sgi.`name`, sem.org_code_path = sgi.org_code_path, sem.org_name_path = sgi.org_name_path, sem.parent_code = sgi.parent_code, sem.update_time = NOW() where sem.`status` = 'NORMAL'
